import{_ as a,o,c as t,a2 as d}from"./chunks/framework.DHmNT4rz.js";const u=JSON.parse('{"title":"Media Storage And Uploads","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"develop/media-storage.md","filePath":"develop/media-storage.md","lastUpdated":null}'),s={name:"develop/media-storage.md"};function r(i,e,l,n,c,p){return o(),t("div",null,[...e[0]||(e[0]=[d(`<div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This page mirrors <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.agents/media-storage.md" target="_blank" rel="noreferrer"><code>.agents/media-storage.md</code></a> from the repository. Edit it at the source, not here.</p></div><h1 id="media-storage-and-uploads" tabindex="-1">Media Storage And Uploads <a class="header-anchor" href="#media-storage-and-uploads" aria-label="Permalink to &quot;Media Storage And Uploads&quot;">​</a></h1><p>Use this when introducing or changing S3-compatible object storage, upload contracts, object-delete behavior, or the database record that tracks uploaded files.</p><p>This repo ships local-disk media storage for development and small deployments.</p><h2 id="current-implementation" tabindex="-1">Current Implementation <a class="header-anchor" href="#current-implementation" aria-label="Permalink to &quot;Current Implementation&quot;">​</a></h2><ul><li><strong>Provider</strong>: local filesystem via <code>MEDIA_UPLOAD_DIR</code> (default <code>.uploads</code>), or MinIO/S3 via <code>files-sdk</code> when <code>MINIO_*</code> env vars are set</li><li><strong>Public URLs</strong>: <code>MEDIA_PUBLIC_BASE_URL</code> (default <code>http://localhost:5000/server/media</code>) for <strong>linked avatars only</strong></li><li><strong>Private downloads</strong>: workspace data exports use authenticated <code>/exports/:id/download</code> (local stream or short-lived signed GET for object storage); attachment/export/private purposes are never served from the public media handler</li><li><strong>Packages</strong>: shared limits/contracts in <code>packages/core</code>, rows and lifecycle queries in <code>packages/db</code>, storage/export services in <code>packages/app</code>, authenticated download authorization in <code>packages/api</code>, and HTTP streaming in <code>apps/server</code></li><li><strong>Upload flow</strong>: signed PUT to <code>apps/server</code> <code>/media/upload/:assetId</code>, then <code>completeAvatarUpload</code> links the asset</li><li><strong>Delete policy</strong>: synchronized hard delete for explicit removals; replaced avatars are marked <code>replacedAt</code> and purged by the storage cleanup schedule after the new link succeeds</li><li><strong>Cleanup</strong>: BullMQ schedule job <code>cleanup-storage</code> (<code>WORKER_SCHEDULE_STORAGE_CLEANUP_CRON</code>, default <code>30 4 * * *</code>) purges expired pending uploads, uploaded orphans, replaced avatars, expired export files, stale failed exports, and local DB/object mismatches</li></ul><p>This file is prescriptive for extensions and should stay aligned with the running code.</p><p>This guide should stay aligned with:</p><ul><li><a href="/SaaSWeave/develop/core">Core package patterns</a></li><li><a href="/SaaSWeave/develop/environment-variables">Environment variables</a></li><li><a href="/SaaSWeave/develop/orpc">oRPC patterns</a></li><li><a href="/SaaSWeave/develop/workflow">Workflow</a></li></ul><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ul><li>Treat <code>media_asset</code> as a generic object-storage record. Current purposes are <code>avatar</code>, <code>attachment</code>, <code>export</code>, and <code>private</code>; add a purpose to the shared contract instead of creating feature-specific storage metadata.</li><li>Keep object-storage metadata generic: owner, purpose, key, content type, size, lifecycle timestamps (<code>uploadedAt</code>, <code>linkedAt</code>, <code>replacedAt</code>), and status. Derive delivery URLs from config and <code>key</code> instead of persisting them on the row.</li><li>Keep business metadata on the owning row, not on <code>media_asset</code>. Alt text, captions, labels, and document titles belong to the domain record that links to the object.</li><li>Default to direct browser-to-storage uploads, with the API brokering signed contracts and lifecycle state.</li><li>Default to synchronized hard delete because it is the simplest lifecycle that does not require a sweeper or retry worker. Background cleanup covers abandoned uploads, replaced avatars, and expired exports.</li><li>Keep soft-delete capability available for future exceptions, but do not build around it by default.</li></ul><h2 id="delivery-policy" tabindex="-1">Delivery Policy <a class="header-anchor" href="#delivery-policy" aria-label="Permalink to &quot;Delivery Policy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Asset class</th><th>Public handler</th><th>Download path</th></tr></thead><tbody><tr><td>Linked avatar</td><td>Yes (<code>status=linked</code>, <code>purpose=avatar</code>, <code>replacedAt=null</code>)</td><td>Public media URL</td></tr><tr><td>Pending / orphaned upload</td><td>No</td><td>Not downloadable</td></tr><tr><td>Attachment / private asset</td><td>No</td><td>Authenticated or signed download when product flows add them</td></tr><tr><td>Workspace data export</td><td>No</td><td>Session-authenticated <code>/exports/:id/download</code> or signed GET URL from <code>console.dataExport.download</code></td></tr></tbody></table><p>Public media route rules:</p><ul><li>Normalize keys with <code>normalizeMediaKey()</code> and resolve files with <code>resolveSafeMediaPath()</code> so corrupted DB keys cannot escape <code>MEDIA_UPLOAD_DIR</code>.</li><li>Never serve <code>pending</code>, <code>uploaded</code>, <code>orphan</code>, <code>deleted</code>, non-avatar purposes, or rows with <code>replacedAt</code> set. Public delivery requires <code>status=linked</code>, <code>purpose=avatar</code>, and <code>replacedAt=null</code>.</li></ul><p>Data export rules:</p><ul><li>Only workspace owners/admins may download.</li><li>Export must be <code>ready</code>, unexpired (<code>expiresAt</code>), and not revoked (<code>downloadRevokedAt</code>).</li><li>Local storage streams with <code>Content-Disposition: attachment</code>, <code>Cache-Control: private, no-store</code>, <code>X-Content-Type-Options: nosniff</code>, and <code>MAX_DATA_EXPORT_DOWNLOAD_BYTES</code>.</li><li>Object storage uses <code>getPrivateFilesClient()</code> and a short-lived signed GET. Never resolve exports through the public client or <code>MINIO_PUBLIC_BASE_URL</code>; <code>files-sdk</code> skips signing when <code>publicBaseUrl</code> is configured.</li><li>Export generation is streaming NDJSON and bounded by shared row/byte limits. A retry starts a new temporary artifact and restarts the export from the beginning; progress counters are operational only, not resumable checkpoints.</li></ul><h2 id="recommended-library" tabindex="-1">Recommended Library <a class="header-anchor" href="#recommended-library" aria-label="Permalink to &quot;Recommended Library&quot;">​</a></h2><p>Use <code>files-sdk</code> for object storage access and signed uploads.</p><p>Default choice for this template:</p><ul><li><code>files-sdk</code></li><li><code>files-sdk/minio</code> for MinIO or other S3-compatible endpoints</li></ul><p>When the repo uses <code>files-sdk</code>, prefer adapter-provided URL resolution such as <code>await files.url(key)</code> over hand-rolled public URL helpers. For exports and private assets, always pass <code>expiresIn</code> so <code>url()</code> returns a presigned GET.</p><h2 id="default-package-shape" tabindex="-1">Default Package Shape <a class="header-anchor" href="#default-package-shape" aria-label="Permalink to &quot;Default Package Shape&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/core/src/media-asset/</span></span>
<span class="line"><span>packages/core/src/data-export/</span></span>
<span class="line"><span>packages/db/src/schema/media-asset.schema.ts</span></span>
<span class="line"><span>packages/db/src/schema/data-export-request.schema.ts</span></span>
<span class="line"><span>packages/db/src/media-lifecycle.ts</span></span>
<span class="line"><span>packages/app/src/storage/media-asset/index.ts</span></span>
<span class="line"><span>packages/app/src/storage/media-cleanup.ts</span></span>
<span class="line"><span>packages/app/src/data-export/{process,storage,stream-export,stream-writer}.ts</span></span>
<span class="line"><span>packages/api/src/lib/data-export/download.ts</span></span>
<span class="line"><span>apps/server/src/routes/media.ts</span></span>
<span class="line"><span>apps/server/src/routes/data-export.ts</span></span></code></pre></div><h2 id="upload-completion-object-storage" tabindex="-1">Upload Completion (Object Storage) <a class="header-anchor" href="#upload-completion-object-storage" aria-label="Permalink to &quot;Upload Completion (Object Storage)&quot;">​</a></h2><p><code>completeMediaAssetUpload()</code> confirms the object with <code>files.head(key)</code> and validates actual <code>size</code> and <code>contentType</code> against the pending row before promoting state. Client-declared metadata alone is not trusted.</p><h2 id="avatar-replacement" tabindex="-1">Avatar Replacement <a class="header-anchor" href="#avatar-replacement" aria-label="Permalink to &quot;Avatar Replacement&quot;">​</a></h2><p><code>completeAvatarUpload</code> links the new asset, updates <code>user.image</code>, then marks prior linked avatar rows with <code>replacedAt</code>. The old object is deleted only after the new link succeeds, via the storage cleanup job (or explicit delete helpers).</p><h2 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h2><p>Storage-related server env names:</p><ul><li><code>MEDIA_UPLOAD_DIR</code></li><li><code>MEDIA_PUBLIC_BASE_URL</code></li><li><code>MINIO_ENDPOINT</code>, <code>MINIO_BUCKET</code>, <code>MINIO_ACCESS_KEY_ID</code>, <code>MINIO_SECRET_ACCESS_KEY</code></li><li><code>MINIO_PUBLIC_BASE_URL</code> (optional; used only for public avatar URL resolution, not exports)</li><li><code>WORKER_SCHEDULE_STORAGE_CLEANUP_CRON</code></li></ul><p>For env propagation and the exact update checklist, follow <a href="/SaaSWeave/develop/environment-variables">Environment variables</a>.</p><h2 id="permission-and-policy-checklist" tabindex="-1">Permission And Policy Checklist <a class="header-anchor" href="#permission-and-policy-checklist" aria-label="Permalink to &quot;Permission And Policy Checklist&quot;">​</a></h2><ul><li>Public-read and signed-read strategies stay separate.</li><li>Workspace exports never route through <code>/media/*</code>.</li><li>Browser upload CORS and size/content-type validation remain enforced in application code.</li><li>Cleanup jobs are idempotent, chunked (<code>MEDIA_CLEANUP_CHUNK_SIZE</code>), and emit audit events without file keys in metadata.</li></ul>`,34)])])}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
